#!/usr/bin/env python3
"""Source-grounded future route, never runtime loader acceptance."""
import pathlib,os,json,hashlib
t=pathlib.Path(os.environ['GLIBC_TASK']);gnu=t/'source/glibc-2.44';nightly=pathlib.Path(os.environ['GLIBC_NIGHTLY_SOURCE'])
units=[(gnu/'dlfcn/dlopen.c',[70,106]),(gnu/'dlfcn/dlmopen.c',[30,107]),(gnu/'dlfcn/dlsym.c',[50,91]),(gnu/'dlfcn/dlvsym.c',[54,96]),(gnu/'dlfcn/dlerror.c',[35,86]),(gnu/'elf/dl-open.c',[860,895]),(gnu/'elf/dl-sym.c',[80,173]),(nightly/'nsprpub/pr/src/linking/prlink.c',[95,165,694,735,851,895])]
evidence=[]
for p,lines in units:
 data=p.read_bytes();evidence.append({'source':str(p.resolve()),'sha256':hashlib.sha256(data).hexdigest(),'relevantLines':lines})
plan={'status':'source plan only; loader not implemented or accepted','evidence':evidence,'initialSupportedModel':'one native Wasm owning module; linked static libraries share process scope and use explicit export registration','GNUAPI':['dlopen(NULL) genuine process handle/reference lifecycle','dlopen registered static names with audited GNU flag validation','dlsym on process/registered handles via native function/data export registry','dlvsym requires explicit symbol version records or honest GNU error','dlclose maintains real handle references; no pretend code unloading','dlmopen retains GNU static namespace rejection','dlerror remains genuine GNU per-thread one-shot error state','RTLD_DEFAULT/RTLD_NEXT need explicit architecture scope/order and caller identity acceptance'],
 'architectureWork':['select owned GNU sysdeps backend rather than removing dlfcn APIs','preserve GNU public entry/error wrappers and actual _dl_catch/_dl_signal error machinery','native function pointers are table indices; data addresses are linear memory; never ELF load-bias arithmetic for both','register explicit symbol kind, native value, module owner and optional version; reject unsupported TLS symbol address without real TLS resolver','provide meaningful nonnull owning-module caller provenance; compiler/architecture hook must cover every accepted call path','only one owning module initially: static registrations cannot pretend separate dynamic module caller ranges','multi-module lookup/RTLD_NEXT needs actual module ordering and caller-to-module mapping before acceptance','unsupported ELF files, relocations, namespaces and dynamic loading return real errors'],
 'NSPR':['_PR_InitLinker still requires dlopen(NULL) and aborts if it fails','PR_LoadStaticLibrary installs actual PRStaticLinkTable and shares executable handle','staticTable lookup returns registered function address, and a miss fails without dlsym fallback','normal PR_LoadLibrary and non-static PR_FindSymbol still need GNU dlopen/dlsym','PR_UnloadLibrary invokes dlclose on shared executable handle; reference handling must preserve process lifetime'],
 'requiredExecutableGates':['GNU public/hidden process handle aliases and stable identity/reference counts','registered function invocation native and FPCAST signatures plus distinct data addresses','symbol misses and GNU dlerror read-once state with thread isolation','invalid flags/namespace/ELF paths honest failures, no null caller shortcut','RTLD_DEFAULT and caller-aware RTLD_NEXT ordering/error cases','nested/reentrant lookup and indirect API call behavior explicitly accepted or rejected','versioned/TLS symbols explicit supported boundaries','actual NSPR init/static registration/find/unload once genuine NSPR/GNU threading dependencies close'],
 'notSolved':['full ELF loader/CRT/sysroot','multi-module native Wasm instantiation and per-module TLS','GNU NPTL forced unwind/C++ cleanup','generic return-address/backtrace semantics','Nightly fault-handler SA_ONSTACK/live callback jump restrictions']}
(t/'logs/static-loader-plan.json').write_text(json.dumps(plan,indent=2)+'\n')
